def process(clean_categories) -> pd.DataFrame:
    max_reports = clean_categories['reports'].max()
    min_reports = clean_categories['reports'].min()
    ratio = max_reports / min_reports
    ratio_rounded = round(ratio, 2)
    return pd.DataFrame({
        'max_reports': [max_reports],
        'min_reports': [min_reports],
        'ratio': [ratio_rounded]
    })
